    bag_examples_v2_toast: "🎁 Új példák a táskádban: ajándékötletek, egy szállodai és egy repülős lista ✨",
    faq_a_bag_examples_list: "Az új táska példákkal érkezik, amelyeket bármi máshoz hasonlóan módosíthatsz vagy törölhetsz: Otthon (bevásárlás, receptek, a hét ételei), Család (apró pillanatok, lista a szülinapi bulihoz, különórák és programok), Ötletek (hétvégi ötletek, ajándékötletek kategóriák szerint, és hogy mit kezdj a megtakarított pénzzel) és Utazások (helyek, ahová el szeretnél jutni, csomagolási lista az útra, csomagolás szállodába és repülés külföldre). A már meglévő táska egyszer megkapja a legújabbakat, a saját zsebeibe.",
    faq_q_bag_examples_list: "Milyen példák vannak a Táskámban?",
    faq_a_nm_me1_guide: "Sky – a karaktered a New Me-ben, az első alakjában (Sky 1). Az első alkalommal, rögtön a csatlakozás után kinyílik egy fényportál, körülötte szikrák csillognak, kirepül belőle Sky, néhány koppintással elmondja, mi vár rád, aztán minden kérdés mellett ott marad: az étkezések kiválasztása közben veled együtt ír a könyvébe, és egy koppintás a tippjére egy újabbat mutat. A végén Sky veled ünnepel, és elvisz egy rövid körútra – és amikor a körút véget ér, még van egy kis közös pillanata veled. Ha félúton kilépsz – a kérdéseknél vagy a körút közben –, legközelebb Sky örül, hogy lát, és megkérdezi, folytassátok-e ugyanonnan.",
    faq_q_nm_me1_guide: "Ki kísér be a New Me-be?",
    nm_m1_day_text: "Minden nap – egy ✓ minden étkezésnél, és én mindent kiszámolok helyetted.",
    nm_m1_go: "Induljunk",
    nm_m1_heart_btn: "Együtt",
    nm_m1_heart_text: "Lépésről lépésre. Itt vagyok – mindig.",
    nm_m1_heart_title: "Járjuk végig együtt ezt az utat",
