    nm_m1_joy_text: "Vár a menüd, és a varázslatos világ már ébredezik.",
    nm_m1_joy_title: "Hurrá! Minden kész",
    nm_m1_magic_text: "És minden igazi lépésed előre újabb helyeket nyit meg a varázslatos világban",
    nm_m1_menu_text: "Együtt összerakunk egy menüt, ami pont rád szabott: ételek, amiket szeretsz, neked kényelmes időpontokban.",
    nm_m1_portal: "Egy új világ nyílik meg",
    nm_m1_q_about: "Örülök, hogy megismerhetlek!",
    nm_m1_q_agree: "Mielőtt belekezdünk – néhány fontos szó",
    nm_m1_q_letter: "Néhány szó a jövőbeli önmagadnak? Biztonságban megőrzöm neked",
    nm_m1_q_menu: "Írjuk le együtt az álmokat – és váltsuk valóra együtt",
    nm_m1_q_plan: "Bármikor válthatsz – itt nincs rossz választás.",
    nm_m1_q_times: "A te időpontjaid az enyémek is",
    nm_m1_ready_text: "Előbb néhány apró kérdés – aztán együtt választjuk ki az étkezéseket.",
    nm_m1_skip: "Kihagyás",
    nm_m1_tip_ai: "Olyan étel, ami nincs a listán? Később a „Csere” részben saját szavaiddal leírhatod – és az AI kiszámolja. Most pedig válasszuk ki együtt, mit eszel minden nap.",
    nm_m1_tip_love: "És ha valamit nem szeretsz – az AI segítségével mindig kicserélheted. Mindegy, milyen étel – ha szereted, a menüben marad.",
    nm_m1_tip_rice: "A rizst szeretem a legjobban – ez lesz az alapom, ezért ezt választom. Azt ajánlom, hogy maradj annál, ami ismerős és finom.",
    faq_a_shop_basics: "Amikor a Bevásárlólista teljesen üres – például a legelején –, megjelenik egy alaplista kezdésnek: tej, kenyér, tojás és még sok más. Egy koppintás egy tételre hozzáadja a listához, az „Összes hozzáadása” pedig mindent egyszerre hozzáad. Amint van valami a listán, az alaplista eltűnik.",
    faq_q_shop_basics: "Mi az alaplista egy üres Bevásárlólistán?",
    shop_basics_all: "Összes hozzáadása",
    shop_basics_items: "tej|kenyér|tojás|paradicsom|uborka|sajt|rizs|tészta|olívaolaj|alma|banán|vécépapír",
    shop_basics_title: "Egy alaplista kezdésnek",
    shop_order_empty: "A lista most üres",
    shop_order_hours: "Hány órakor?",
    shop_win_evening: "Este",
