    shop_win_morning: "Délelőtt",
    shop_win_noon: "Délután",
    shop_win_other: "Egyéb…",
    shop_win_to: "Eddig",
    room_genie_again_no: "Most nem",
    room_genie_again_no_msg: "Akkor itt az ideje elérni a céljaidat, amelyeket már kitűztél. Ha eljutsz a következőhöz – ott vár rád valami ✨",
    room_genie_again_q: "Újra itt? ✨ Szeretnél még valamit megváltoztatni az életedben?",
    room_genie_again_yes: "Igen",
    room_genie_bye: "Viszlát",
    room_genie_rest: "Az erdei szellem most pihen – gyere vissza holnap ✨",
    faq_a_shop_holidays: "A Bevásárlólistán koppints az ajándékra: sorban megjelennek az országod (a Beállításokban megadott ország) ünnepei, a dátumukkal együtt – ezeket minden évben magától kiszámolja. Koppints egy ünnepre, és megnyílik egy kész lista arról, amit ilyenkor venni szoktak; minden ki van jelölve (kivéve, ami már a listádon van), vedd ki a pipát abból, amire nincs szükséged, és koppints a „Hozzáadás a listához” gombra. Két héttel egy ünnep előtt egy kis kártya jelenik meg a lista tetején; a ✕ elrejti a következő ünnepig.",
    faq_q_shop_holidays: "Hogyan működik a „Mit vegyünk az ünnepre”?",
    shop_hol_add: "Hozzáadás a listához ({n})",
    shop_hol_added: "Hozzáadva a listához: {n}",
    shop_hol_btn: "Mit vegyünk az ünnepre",
    shop_hol_items_title: "{holiday} – mit vegyünk?",
    shop_hol_not_now: "Most nem",
    faq_a_shop_delivery: "A Bevásárlólistán koppints a teherautóra: válaszd ki, mi van a szállítmányban (minden ki van jelölve), mikor érkezik – ma, holnap vagy egy másik napon – és melyik napszakban (délelőtt, délután, este vagy „Egyéb…” a saját időpontodhoz). Ezek a tételek a lista tetején lévő „Úton” kártyára kerülnek, a nappal és az időponttal együtt. Amikor eljön a nap, A Napomban megjelenik a „Megérkezett a szállítmány?” kérdés (a kártyán pedig ott a „Megérkezett?”). Ha minden megérkezett, az „Újravásárlás” részbe kerülnek. Ha valami hiányzik, koppints arra, ami nem érkezett meg, és egyből visszakerül a listára.",
    faq_a_shop_departments: "A lista magától a szupermarket részlegei szerint rendeződik – zöldség és gyümölcs, pékáru, tejtermék és tojás, hús és hal, szárazáru, fagyasztott, italok, nassolnivaló, tisztítószer, drogéria, baba és kisállat –, így sorrendben járhatod végig a polcokat. A részleget a tétel neve alapján ismeri fel. Ha egy tétel rossz helyre került, koppints rá, és válaszd ki a részlegét, vagy az „Egyéb…” lehetőséget, hogy magad írd be.",
    faq_a_shop_share_qty: "Igen. Minden tétel mellett a + hozzáad egyet (×2, ×3…), a − pedig elvesz egyet. A Bevásárlólista tetején lévő megosztás gomb az egész listát elküldi részlegek szerint szépen rendezve WhatsAppon, e-mailben vagy másolatként.",
    faq_a_shop_two_buttons: "Mindkettő azt jelenti: „megvéve”. A ✕ arra való, amit egyszer veszel meg – lekerül a listáról (és a 🗑️ archívumban vár, ha tévedés volt). A ↺ arra, amit újra és újra megveszel – lekerül a listáról, és az „Újravásárlás” részben vár: ezt a lista alján, a kuka melletti kis ↺ gomb nyitja meg, és ott egy koppintás visszatesz egy tételt a listára. Benne a „Szerkesztés” alatt kivehetsz belőle egy tételt. Amikor hozzáadsz egy tételt, a korábban megvett dolgok javaslatként jelennek meg, és ha már a listán van, egyszerűen ×2 lesz belőle egy második sor helyett.",
    faq_q_shop_delivery: "Hogyan működik a „Házhozszállítást rendeltem”?",
    faq_q_shop_departments: "Miért van részlegekre osztva a bevásárlólistám?",
