    nm_demo_title: "Így működik a csere",
    faq_a_new_me_challenge_journal: "Amikor egy kihívás véget ér – nagy, mini vagy a hét kihívása –, az ünneplésben van egy 📝 Hogy ment? gomb. Ez megnyit egy oldalt a kihívásnaplóban: milyen volt (öt arc), mi segített, mi volt nehéz és mit viszek magammal tovább – egyik sem kötelező, és később is ráér. A napló egy gyémánt a varázslatos hátizsákban: minden befejezett kihívás a dátumával és a beírt szöveggel, a legújabb elöl – koppints egyre, hogy elolvasd, szerkeszd vagy megoszd (csak az lesz megosztva, ami az oldalon van). A befejezett kihívás egy érmet is kap a kitüntetések között, a „Teljesített kihívásaim” alatt. A kihívásnapló független a megszokott naplótól.",
    faq_q_new_me_challenge_journal: "Mi az a kihívásnapló?",
    nm_badges_challenges: "Teljesített kihívásaim",
    nm_chj_empty: "Itt jelennek meg a kihívások, amelyeket befejezel",
    nm_chj_hard: "Mi volt nehéz?",
    nm_chj_helped: "Mi segített?",
    nm_chj_later: "Később",
    nm_chj_mood_1: "Nagyon nehéz",
