    nm_chj_q: "Hogy ment a kihívás?",
    nm_chj_reflect_btn: "Hogy ment?",
    nm_chj_save: "Mentés a kihívásnaplóba",
    nm_chj_saved: "Elmentve a kihívásnaplóba",
    nm_chj_share_text: "Teljesítettem egy kihívást a New Me-ben ✨",
    nm_chj_take: "Mit viszek magammal tovább?",
    nm_chj_title: "Kihívásnapló",
    nm_chj_write: "Írd le, hogy ment",
    nm_swap_time: "Időpont",
    faq_a_ai_reminder_in_text: "Igen – írd a feladattal együtt, például „holnap 17:00-kor elhozni a csomagot, emlékeztetővel egy órával előtte”. Az emlékeztető magához a feladathoz mentődik el: egy órával előtte, fél órával, egy nappal előtte és így tovább, időpont nélkül pedig az „emlékeztess” 10 perccel előtte érkező emlékeztetőt jelent. A szövegbe írt emlékeztető elsőbbséget élvez ugyanannak az ablaknak az emlékeztető mezőjével szemben.",
    faq_q_ai_reminder_in_text: "Kérhetek emlékeztetőt az AI-asszisztenstől ugyanabban a kérésben?",
    myday_meals_all_done: "A mai összes étkezés ki van pipálva 🍽️",
    nm_tour_week_text: "Egy apró kihívás a hétre. ✓ minden nap – a végén egy kulcs.",
    books_home_chip: "{title} · {page}. o.",
    books_home_of: "/ {total}",
    books_home_off_toast: "A könyv lekerült a kezdőképernyőről",
    books_home_on_toast: "A könyv a kezdőképernyőn van 📖",
    books_home_pin: "A kezdőképernyőn",
    books_home_q: "Hányadik oldalon tartok?",
    books_home_save: "Mentés",
    faq_a_books_home_chip: "Igen. Az Olvasósarokban, egy éppen olvasott könyv kártyáján koppints a 📌 A kezdőképernyőn gombra. A kezdőképernyőn, a köszöntés alatt megjelenik egy kis gomb a könyvvel és az oldallal – koppints rá, írd be az új oldalszámot, és mentsd el, így követhető a haladás (az Olvasósarokban is). A 📌 ismételt megérintése leveszi. Több könyv is lehet ott egyszerre – mindegyikhez egy gomb –, és minden eszközön ugyanaz.",
    faq_a_new_me_week_challenge: "Egy apró kihívás egy hétre, amelyet te választasz. A folyosón van egy nagy kártya: „Min szeretnél dolgozni ezen a héten?” – koppints rá, válassz egy területet (önmagammal, másokkal, tanulás és fejlődés, nyugalom, apró bátor lépések, otthon és rutin) és egy kihívást, és válaszd ki, mikor induljon. Ugyanezek a kihívások a kihívások képernyőjén is megvannak, a 🌱 Személyes fejlődés alatt. Minden nap pipálj egy ✓-t a kártyán (hetente egy szabadnap), és minden lezárult hét új kulcsot hoz a titkos világhoz. A „Naponta 2 oldal olvasása” magától pipálódik az Olvasósarokban rögzített oldalakból. A hét végén a 📌 Megtartás napi feladatként hozzáadja a Rutinomhoz a választott időpontban, minden nap egy ✓-val. Egyszerre egy heti kihívás fut; a nagy és a mini kihívások mellette tovább mennek.",
    faq_a_room_genie: "A tengerre néző verandán Aladdin lámpájának megérintésére előbújik az erdei szellem – és beszélgetés indul: mi a kívánságod (mit változtatnál meg az életedben), milyen érzés lesz, ha valóra válik, mi a nehéz az úton, és hogyan fordítható a mostani helyzet jóra. Aztán nagyjából mennyi idő kell hozzá, egy első apró lépés és még kettő, valamint egy „ha… akkor…” a nehéz pillanatokra. A végén megjelenik az egész kívánság lépésről lépésre, és céllá alakítható a Céljaimban (a lépések az ösvény mérföldkövei lesznek, a választott idő szerinti dátummal; ott minden megváltoztatható), vagy elmenthető a naplóba – és ekkor a szellem elköszön. Semmi nem mentődik, ha nem választod valamelyiket. A második látogatástól a szellem először megkérdezi, szeretnél-e még valamit megváltoztatni az életedben: igen – ugyanaz a beszélgetés; most nem – emlékeztető a már kitűzött célok elérésére. A szellem naponta egyszer jön elő: miután egy kívánság elmentődött (vagy a „Most nem” után), holnapig pihen. A kérdések egy ismert módszert követnek, amely a kívánságból tervet csinál: kívánság, eredmény, akadály és terv.",
    faq_q_books_home_chip: "Láthatom a könyvemet és az oldalt a kezdőképernyőn?",
    faq_q_new_me_week_challenge: "Mi a hét kihívása?",
