    room_drawer_aria: "Kis szekrény",
    nm_me_choose: "Kiválasztás",
    nm_me_on_screen: "A képernyőn",
    faq_a_new_me_game: "A New Me-ben a játék gombjai mindig ugyanott maradnak – a folyosón, a titkos szobában és az erdőben mindenhol; csak a középen lévő festmény változik. Fent: a nap az úton, a kulcsok, a sorozat és a mai energia (mennyi fogyott el a tervből), alatta pedig a következő küldetés – a következő étkezés az időpontjával (egy koppintás megnyitja, ✓ Megettem gombbal). Az oldalon: az egész nap, kihívások és az utam, mellettük pedig a hét kihívása – a 7 napja és egy ✓ mára. Alul: a varázslatos hátizsák (az egész New Me – világtérkép, az utam, bevásárlólista, kitüntetések, kihívásnapló, testméretek, fotók, havi naptár, napi táblázat, emlékeztetők, menü PDF és beállítások; külön képernyőként nyílik meg). A világtérkép, a hátizsák első eleme, az erdő minden helyét megmutatja – koppints egy helyre, hogy odamenj; egy zárt helyen látszik, hány kulcs kell hozzá. Sky a karaktered az erdei ösvényen: eleinte Sky 1, néhány kihívás után (4 kulcs) Sky 2 lesz belőle, a vége felé (9 kulcs) pedig Sky 3 – egy átalakulással, amit végig lehet nézni. Egy koppintás a karakterre (Sky) megmutatja az összes szakaszt – bármelyik már elért szakasz újra kiválasztható, így egy korábbi is visszatérhet. Sky lebeg – ujjal vagy egérrel húzható, és a bejárat, amelyet megérint, kinyílik (a zárt bejáratnál látszik, hány kulcs hiányzik). Sky minden szobába és helyre is veled tart, és ott lebeg, ahol hagyod: húzd bárhová, és az alatta lévő világító gyűrűt húzva teljesen körbe is fordíthatod; arra néz, amerre halad (számítógépen: a nyilak mozgatják, a Q és az E forgatja). A folyosón a felső sáv alatti kis 🏠 visszavisz a kezdőképernyőre; minden szobában és helyen az ugyanabban a sarokban lévő gomb visszavisz a folyosóra.",
    faq_q_new_me_game: "Hogyan működnek a játék gombjai, a világtérkép és Sky?",
