    room_magic_song_rec3: "A vízesés csengői",
    faq_a_new_me_menu_build: "Először a kérdőív megkérdezi, milyen étkezéseid vannak és mikor (2 étkezés + egy nasi, 2 étkezés + egy könnyű vacsora, vagy mindkettő), és hogy van-e valami este – ennivaló vagy innivaló, mi, és hánykor. A „2 étkezés + egy nasi” esetén az étkezések az ebéd (11:30) és a vacsora (19:00), a nasi pedig 16:00-kor van. Ezután megjelenik az összes lehetőség ezekhez az étkezésekhez. Minden étkezéshez legfeljebb 2 kedvencet választhatsz – a menüben ez áll: „ez vagy az”. Néhány lehetőségnél (pita és krém, kukoricapehely tejjel, valami könnyű) legfeljebb 3 dolgot választhatsz, amit szeretsz, mindegyiket a saját adagjában, és a menüben ez áll: „ez vagy az vagy amaz”; a kalória a választásodat követi. A kávé és az italok ugyanígy működnek. Minden választás kiegyensúlyozott, így a nap pontosan 1300 vagy 1500. Bármikor módosíthatod: ⚙️ Beállítások → 🍽️ Állítsd össze a menüdet, vagy „Válassz legfeljebb 3 kedvencet” az étkezés kártyáján.",
    faq_q_new_me_menu_build: "Hogyan épül fel a New Me menü?",
