    faq_a_myday_water_toggle: "Igen. A vizespohár A Napomban (+ gombbal még egy pohárért) alapból látható. Az elrejtéshez kapcsold ki a „Víz megjelenítése A Napomban” kapcsolót a Beállítások > Személyre szabás és naptár menüben. Semmi sem törlődik – a Vízfogyasztás Követése tovább működik, és a kapcsoló visszakapcsolásakor a pohár visszatér.",
