    faq_a_food_list_languages: "A beépített ételek listája izraeli ételekkel és azok héber neveivel indult. Minden más nyelven minden étel az angol nevével jelenik meg, és a keresés megtalál minden angol nevet, amit ismer (például a 'broth' megtalálja a Clear soupot); azok az ételek, amelyeknek csak héber nevük van, ott nem jelennek meg. Ami nincs a listán, egyszerűen leírhatod a saját szavaiddal – az AI-becslés minden nyelven működik.",
    faq_q_food_list_languages: "Miért mutat az ételek listája angol neveket, és kevesebb ételt, az én nyelvemen?",
    settings_copyright_line: "© 2026 minden jog fenntartva. az alkalmazás fejlesztője: eden zabari.",
    workout_ready_replace_btn: "Csere",
    faq_a_sport_workout_ai: "Az „Edzéseim” → ⋯ → „Terv AI-jal” alatt (és ha üres a táblázat, a kész tervek melletti csempén is). Válaszolj néhány koppintással – hetente hányszor, mikor, helyszín, szint és cél, szinte mindegyiknél van „Egyéb” is –, és ha szeretnéd, írj hozzá egy szabad sort, például érzékeny térd vagy 5 km futás nyárig. Az AI egy egész hetet összeállít: edzéstípusokat, napokat, időpontokat, időtartamot, intenzitást, gyakorlatokat és pihenőnapokat. Mielőtt bármi mentődne, előnézet jelenik meg: „Be a táblázatomba” (a táblázat helyett vagy mellé), „Másik javaslat” (legfeljebb 3-szor) vagy „Válaszok módosítása”. A terv szándékosan mértékletes, és ha fájdalmat vagy sérülést említesz, kíméletes lehetőségeket kapsz, valamint azt a tanácsot, hogy beszélj egy szakemberrel. Ugyanazt az AI-keretet használja, mint az órarend és a rutin: 5-ször ingyen, Prémiummal havonta 60-szor.",
    faq_q_sport_workout_ai: "Hogyan készítek edzéstervet AI-jal?",
    workout_ai_add: "A táblázatom mellé",
    workout_ai_again: "Másik javaslat",
    workout_ai_apply: "Be a táblázatomba",
