    workout_ai_other: "Egyéb",
    workout_ai_replace: "A táblázatom helyett",
    workout_ai_title: "Edzésterv AI-jal",
    workout_ai_when_evening: "Este",
    workout_ai_when_label: "Mikor",
    workout_ai_when_morning: "Reggel",
    workout_ai_when_noon: "Délben",
    workout_ai_when_ph: "pl. munka után, vagy 17:30",
    workout_ai_working: "Készül a terv…",
    faq_a_sport_workout_jar: "Minden edzéstípusnak saját színes csillaga van – a futásé rózsaszín, a sétáé zöld, az úszásé kék és így tovább. Minden ezen a héten rögzített edzés, a táblázatból vagy külön, beejti a csillagát az „Edzéseim” tetején lévő üvegbe, és az üveg a heti célig telik (koppints rá a cél módosításához). Ha eléred a célt, az üveg felragyog. A mellette lévő kis üveg azt számolja, hány egymást követő héten telt meg.",
    faq_q_sport_workout_jar: "Mik a színes csillagok és az üveg az „Edzéseim” részben?",
    faq_a_sport_workout_gcal: "Igen – a ⋯ → Google Naptár alatt (miután a Google Naptárt összekapcsoltad a Beállításokban). Minden időponttal rendelkező edzés a saját napjain hetente ismétlődő eseménnyé válik, és az alkalmazásbeli változások azt is frissítik. Emlékeztetőt csak az alkalmazás küld, így a Google nem tesz hozzá sajátot, és az edzések soha nem jelennek meg kétszer az alkalmazásban. Újabb koppintás csak az edzéseket veszi ki a Google Naptárból.",
    faq_q_sport_workout_gcal: "Megjelenhetnek az edzéseim a Google Naptárban?",
    workout_gcal_btn: "Google Naptár",
    workout_gcal_error: "Nem sikerült frissíteni a Google Naptárt – a következő változtatásnál újra próbálkozik",
    workout_gcal_not_connected: "Előbb kapcsold össze a Google Naptárt a Beállításokban",
    workout_gcal_off_toast: "Az edzések kikerültek a Google Naptárból",
    workout_gcal_on_toast: "Az edzéseid bekerültek a Google Naptárba",
    faq_a_sport_workout_reminder: "Igen – egy edzésnél a Emlékeztető: 10 perccel, 30 perccel vagy egy órával előtte, vagy saját időpontban (az edzésnek kell időpont). Úgy szól, mint a többi emlékeztetőd, egyszer és egy helyen: az alkalmazásban, ha nyitva van, különben a telefonodon. A „Kész” rögzíti az edzést az előzményekben, a „Még nem” pedig 5 perc múlva újra szól.",
    faq_q_sport_workout_reminder: "Kaphatok emlékeztetőt edzés előtt?",
    workout_reminder_30min: "30 perccel előtte",
    workout_reminder_label: "Emlékeztető",
    workout_reminder_need_time: "Adj meg időpontot, hogy emlékeztetőt kapj",
    faq_a_sport_workout_share: "A ⋯ → Megosztás alatt a hét üveghatású képpé válik a témád színeiben, egy diszkrét hivatkozással az alkalmazásra (telefonon egyből a megosztás menübe kerül, számítógépen a kép elmentődik). A ⋯ → Nyomtatható PDF az egész hét tiszta oldalát nyitja meg, minden edzés és gyakorlat mellett egy kipipálható négyzettel – válaszd a „Mentés PDF-ként” lehetőséget, vagy nyomtasd ki. A terv a Beállítások adatjelentésében is megjelenik, a Sport résznél.",
    faq_q_sport_workout_share: "Hogyan oszthatom meg vagy nyomtathatom ki az edzéshetemet?",
    share_image_saved: "A kép elmentve – csatolhatod",
    share_save_image: "Kép mentése",
    workout_pdf_btn: "Nyomtatható PDF",
    workout_share_btn: "Megosztás",
    faq_a_sport_workout_board: "A ⋯ → Heti tábla alatt minden nap egy oszlop: húzd az edzést egy másik napra (telefonon előbb nyomd hosszan). Egy edzésnél a „A Rutinomban is” a saját időpontjában és napjain beteszi a rutinodba, és a változások mindkét irányban szinkronban maradnak; a Rutinom egy eleménél a „Hozzáadás az edzéseimhez” ennek a fordítottját teszi. Bármelyik helyen adott ✓ mindkettőben számít, és A Napomban csak egyszer jelenik meg – a víz melletti címkében.",
    faq_q_sport_workout_board: "Hogyan teszek át egy edzést másik napra, és hogyan kötöm a Rutinomhoz?",
    routine_in_workouts_btn: "Megnyitás az edzéseimben",
    routine_to_workout_btn: "Hozzáadás az edzéseimhez",
    routine_to_workout_done: "Hozzáadva az edzéseimhez 💪",
    workout_delete_confirm_routine: "Kikerül a tervből és a Rutinomból. Az előzményekben már rögzített edzések megmaradnak.",
    workout_moved: "Áthelyezve ide: {day}",
    workout_routine_need_time: "Adj meg időpontot, hogy bekerüljön a Rutinomba",
    workout_routine_toggle: "A Rutinomban is",
    workout_view_board: "Heti tábla",
    workout_view_timeline: "Idővonal",
    faq_a_sport_workout_plan: "Az Edzéskövetésben, az „Edzéseim” alatt: + Edzés – típus, napok, időpont, időtartam, intenzitás és helyszín („Egyéb” is). Az erősítő, funkcionális és úszóedzésekhez gyakorlatlista is tartozhat, a „Pihenés” pedig pihenőnapot jelöl. Kész tervvel is kezdhetsz. A mai edzés nagyban látszik, alatta az egész hét; a ✓ az intenzitásával együtt rögzíti az edzésnaplóban. A ⋯ alatt heti célt állítasz be (edzések vagy percek) – minden elvégzett edzés beejti a csillagát az üvegbe.",
    faq_a_sport_workout_today: "A Napomban, a víz mellett egy kis címke mutatja a mai edzést – koppintásra megnyílnak a részletek, a ✓ és a ▶. A ▶ elindít egy időzítőt, amely a kezdőképernyő címkéjében is tovább fut, a „Befejezés” pedig a valódi idővel rögzíti az edzést. Ha a New Me „Két hét mozgás” kihívása fut, a rögzített edzés magától beszámít.",
    faq_q_sport_workout_plan: "Hogyan tervezem meg az edzéshetemet?",
    faq_q_sport_workout_today: "Hol látom a mai edzést, és hogyan működik az időzítő?",
