    dictation_network: "Ez a böngésző nem éri el a diktálási szolgáltatását – próbáld a Chrome-ot vagy az Edge-et",
    dictation_no_mic: "Nem található mikrofon – a számítógéphez csatlakoztatott mikrofon vagy mikrofonos headset kell",
    dictation_no_speech: "Nem hallatszott beszéd – próbáld újra, kicsit közelebb a mikrofonhoz",
    dictation_service_off: "A diktálás ki van kapcsolva ebben a böngészőben vagy ezen a számítógépen – kapcsold be a számítógép beállításaiban, vagy próbáld a Chrome-ot",
    faq_a_new_me_magic_themes: "Öt csillogó téma, amely a New Me része: Varázserdő, Csillagpor, Rózsatündér, Varázslatos sarki fény és Arany alkony. Válassz egyet a New Me-ben (⚙️ Beállítások > Színek) vagy a Beállítások > Megjelenés és kijelző menüben, és egy csillámos ecset átfesti vele a képernyőt. A varázslatos téma csillámot hoz az egész alkalmazásba és minden koppintáshoz. Bármikor visszaválthatsz bármelyik másik témára.",
