    theme_magic_section_label: "A New Me varázslatos témái",
    apptour_focus_text: "Minden félreáll, kivéve az egyetlen mostani dolgot – egy nagy ✓-val. Utána jön a következő.",
    apptour_m_presets_text: "A mentett étkezéseid egy helyen: keresés, legutóbbiak, napszak szerint – és a ＋ hozzáad egyet a mai naphoz.",
    apptour_night_text: "A 🌙 sötétre vált az egész alkalmazást, a ☀️ visszahozza a nappalt.",
    apptour_noteline_text: "Írj, és koppints a ➤-ra – a jegyzeteid közé kerül. Az elején lévő 📝 átvált 🛒 bevásárlásra vagy 🍎 mentett étkezésre.",
    apptour_search_text: "Jegyzetek, bevásárlás, naptár, receptek, füzetek, célok, táblázatok és könyvek – egy keresés mindent megtalál.",
    faq_a_new_me_ai_menu: "Az étlap előtt a kérdőív megkérdezi, milyen étkezéseid vannak és mikor (2 étkezés + egy nasi, 2 étkezés + egy könnyű vacsora, vagy mindkettő), eszel-e este valami kicsit és hánykor, mit nem eszel, és hogyan iszod a kávét vagy a teát. Ezután az AI minden étkezéshez 3 javaslatot készít – mindegyik akkora, amekkora az adott étkezés része a napból, így a nap továbbra is pontosan 1300 vagy 1500 –, valamint italötleteket, amelyek az állandó italaid közé kerülnek. Étkezésenként legfeljebb 2 kedvencet választhatsz; az eredeti étlap javaslatai közvetlenül alattuk vannak, a 🔄 Csere menüben pedig a személyes étlapod után jönnek. A 🔄 Más javaslatok új sorozatot készít (kérdőívenként 3-szor). A válaszok módosításához vagy bármikor új étlaphoz: ⚙️ Beállítások → ✨ Személyes étlap (AI).",
    faq_q_new_me_ai_menu: "Hogyan működik a New Me személyes étlapja?",
    nm_ai_menu_building: "Étlap készül az étkezéseidhez és az időpontjaidhoz…",
    nm_ai_menu_drinks: "Italok neked",
    nm_ai_menu_error: "A személyes étlapot most nem sikerült elkészíteni – itt az eredeti étlap. Próbáld újra, vagy később a ⚙️ Beállítások menüben.",
    nm_ai_menu_original: "Az eredeti étlapról",
