    faq_a_new_me_day_total: "Minden nap pontosan a tervre jön ki: az étkezések, kb. 150 kalória kávéra és italokra a nap folyamán, és amit estére választottál – valami kis ennivaló vagy valami innivaló. Estére válassz legfeljebb 3 kedvencet (például egy banánt, egy joghurtot vagy 2 kocka étcsokoládét; vagy gyógyteát, teát egy kevés tejjel vagy meleg tejet), és ezek kalóriája az étkezésekből jön le. Minden választás magától kiegyenlítődik: kisebb vagy nagyobb lehetőség, kihagyott étkezés, a kis reggeli és a vele járó kis étkezés, vagy az este – a különbség hozzáadódik az étkezésekhez vagy levonódik belőlük, mindegyikhez a mérete szerint, és minden étkezés alatt ott áll, mennyi (+ vagy −), és mit lehet hozzátenni vagy elhagyni. A már kipipált étkezés úgy marad, ahogy rögzítették. A kérdőívben minden étkezés mellett látszik a korrekciója, egy kis doboz pedig az étkezéseket, az italokat, az estét és az összeget mutatja. Kedved támadt aznap valami másra? Az összeg maradjon ugyanannyi kalória vagy kevesebb.",
    faq_q_new_me_day_total: "Hogyan jön ki egy New Me-nap pontosan 1300 / 1500-ra, és hol számítanak az italok?",
