    nm_less_line_late: "{n} kalória ebben az étkezésben, valami kicsiért {time}-kor – például {ideas}",
    nm_swap_balanced: "{n} kalória elosztva az étkezések között, hogy a nap {plan} legyen",
    books_quotes_chip: "Idézetek",
    faq_a_book_quotes: "A titkos szoba polcán (Idézetek), vagy az Olvasósarok kis 💬 Idézetek címkéjével – ugyanaz a lista. Koppints a „+ Idézet” gombra, írd be a mondatot, és válaszd ki a könyvet az Olvasósarokból, vagy írj be más címet az „✏️ Egyéb” segítségével; a szerző nem kötelező. A ✏️ szerkeszti, a 🗑️ törli az idézetet. Az idézetek lapozható könyvjelzők – a fenti 🎨 fotókra vagy kártyafalra vált.",
    faq_a_room_wish_jar: "A titkos szoba polcán áll egy üveg az álmoknak. Koppints a kis üvegre a legfelső polcon (vagy Polc > A kívánságos befőttesüveg), és írd le, milyennek szeretnéd az életedet – bátran, jó és rossz nélkül. Minden kívánság egy összehajtott cetlivé válik, és az üvegbe hull. A „Húzz egy cetlit” véletlenszerűen kinyit egyet, és minden cetli külön is kinyitható. Ugyanannak a kívánságnak a második megnyitásától célt csinálhatsz belőle, és kis lépésekre bonthatod. Hetente egyszer finoman felbukkan egy cetli az egyik kívánságoddal – nyomás nélkül, csak emlékeztetőül, merre tartasz.",
    faq_q_book_quotes: "Hol tarthatom az idézeteket a kedvenc könyveimből?",
    faq_q_room_wish_jar: "Mi a kívánságos befőttesüveg a titkos szobában?",
