    room_wish_written: "Írva: {date}",
    faq_a_saved_meals_page: "A mentett ételeknek saját oldaluk van: Táplálkozás és Mérések > ⭐ Mentett ételek (vagy ⭐ a menüben). A fenti keresés név vagy hozzávaló alapján talál meg egy ételt, a „Nemrég használt” azt mutatja, amit mostanában adtál hozzá, a fülek (Reggeli, Ebéd, Vacsora, Levesek…) pedig a nap minden szakát. A „+ Ma” a mai Napi Étkezéskövetőbe teszi az ételt, a következő szabad helyre. Koppints egy ételre a szerkesztéshez vagy törléshez, a fenti ＋ pedig újat ad hozzá.",
