    presets_tab_snack: "Nasik",
    presets_tab_soup: "Levesek",
    presets_tab_sweet: "Édességek",
    faq_a_notes_sticky_look: "A jegyzetek üvegkártyák rövid listája – a Jegyzetek tetején lévő 🎨 az egész Jegyzetek megjelenését megváltoztatja: a listát, a fenti nap-gombokat és az ablakot, ahol a jegyzet íródik – üveg, letisztult lista, kartotékkártyák vagy washi szalag. A húzott jegyzet pontosan megtartja a saját megjelenését és színét. Koppints egy jegyzet szövegére a megnyitáshoz – ott szerkesztheted, megváltoztathatod a színeit, és láthatod, mikor írták utoljára. Ha kész, koppints a ○ jelre, a × pedig az archívumba teszi (a lista alján a 🗑️ visszahozza). A ⠿ jelnél fogva húzva megváltoztathatod a sorrendet, áthúzhatod a „Később” alá vagy egy fenti napra. A ! sürgősnek jelöli a jegyzetet – finoman felcsúszik az első sorokba egy kis „Sürgős” címkével; egy újabb koppintás leveszi a jelölést.",
    faq_q_notes_sticky_look: "Hogyan nyithatok meg, szerkeszthetek vagy törölhetek egy jegyzetet?",
    note_to_archive_btn: "Áthelyezés az archívumba",
    faq_a_routine_clash: "Ha abban az időpontban ugyanazokon a napokon már van valami, két lehetőség jelenik meg: „Csere” – az új elem kapja ezt az időpontot, a korábbinak pedig másik időpontot választasz (meglévő elem szerkesztésekor annak előző időpontja jelenik meg javaslatként, így a kettő egyszerűen helyet cserél), vagy „Mindkettő” – mindkettő ugyanabban az időpontban marad, egymás alatt. Ha a napok különböznek (például az egyik V–Cs, a másik péntek), semmit sem kérdezünk.",
    faq_q_routine_clash: "Mi történik, ha a napirendben egy már foglalt időpontra teszek valamit?",
    routine_clash_both: "✌️ Mindkettő – mindkettő {time}-kor",
    routine_clash_move_btn: "Áthelyezés és mentés",
    routine_clash_move_to: "Hány órára kerüljön „{title}”?",
    routine_clash_replace: "🔄 Csere – és „{title}” áthelyezése másik időpontra",
    routine_clash_title: "{time}-kor már van: {title}",
    faq_a_new_me_coffee: "A mai menü alatt egy rövid összegzés áll: hány kalória a nap összes étkezése együtt, mennyi maradt kávéra és italokra, és gombok a kiválasztott kávékhoz és italokhoz – egy koppintással bekerül az Italok közé. A gombok alatti „Válassz legfeljebb 3 kedvencet” részben (és a kérdőívben) választhatod ki, mi jelenjen meg: víz / szódavíz, gyógytea, diétás üdítő, fekete / americano (~5), tea egy kevés tejjel (~25), vízzel készült kávé legfeljebb 100 ml tejjel vagy növényi itallal (~50), light kakaó, meleg tej vagy sima kávé / latte (~120).",
    faq_q_new_me_coffee: "Hol adom hozzá a kávét, és honnan tudom, mennyi maradt a napból?",
