    nm_late_room_line: "Valami apróság lefekvés előtt · ma még ~{n} kcal maradt",
    faq_a_recipe_examples: "A saját receptjeid alatt mintareceptek vannak: reggelik, saláták, levesek, főételek, köretek, nassolnivalók, desszertek és vegán ételek, mindegyiknél az elkészítési idővel, az adagonkénti kalóriával és azzal, hány gramm egy adag. Koppints egy receptre a megnyitásához, a „Mentés a Receptjeim közé” pedig saját, szerkeszthető másolatot készít. A kategóriacímkék szűrnek, és ugyanarra a címkére még egyszer koppintva újra minden látszik.",
    faq_a_recipe_grams: "A receptben a kalória mellett ez áll: „1 adag ≈ X g”. A saját receptjeidnél töltsd ki a recept űrlapján a „Gramm adagonként” mezőt (és ha szeretnéd, az elkészítési időt): mindkettő elhagyható, az idő pedig a recept színes sávján jelenik meg.",
    faq_q_recipe_examples: "Mik a mintareceptek a Receptjeim között?",
    faq_q_recipe_grams: "Hogyan látom, hány gramm egy adag?",
    recipe_category_vegan: "Vegán",
    recipe_grams_placeholder: "Gramm adagonként",
    recipe_meta_grams: "1 adag ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} perc",
    recipe_minutes_placeholder: "Elkészítési idő (perc)",
    recipe_save_example_btn: "Mentés a Receptjeim közé",
    recipe_saved_example: "✓ A Receptjeim között van",
    recipe_saved_example_toast: "Elmentve a Receptjeim közé – ott szerkesztheted",
    recipes_examples_title: "Mintareceptek",
    faq_a_recipe_scan_multi: "Igen. A „Recept Hozzáadása” ablakban koppints a 📷-ra, és válassz egy vagy több fotót (legfeljebb 6-ot; PDF is jó). Mindegyik megjelenik egy rövid listában, ahol kiválasztod, mi van rajta: Mind, Hozzávalók vagy Elkészítés, a „➕ Még egy fotó” pedig újabbat ad hozzá. Utána koppints a „✨ Recept beolvasása” gombra: az AI mindent egyetlen receptté fűz össze, sorrendben és ismétlődő sorok nélkül, és ez egy beolvasásnak számít. Az AI-asszisztens 📷 Fotó gombjával kiválasztott több fotó is itt nyílik meg.",
    faq_q_recipe_scan_multi: "Beolvasható egy recept több fotóról, például külön a hozzávalók és az elkészítés, vagy két oldal?",
    recipe_scan_add_more: "➕ Még egy fotó",
    recipe_scan_part_all: "Mind",
    recipe_scan_part_ingredients: "Hozzávalók",
    recipe_scan_part_steps: "Elkészítés",
    recipe_scan_remove_photo: "Fotó eltávolítása",
    recipe_scan_run_btn: "✨ Recept beolvasása",
    recipe_scan_too_many: "Receptenként legfeljebb {n} fotó",
    faq_a_note_written_at: "Koppints a jegyzet szövegére a megnyitásához. Benne, a szöveg alatt látszik, mikor írták utoljára, pontos dátummal és időponttal. Csak a szöveg módosítása frissíti: az archiválás és visszaállítás, a ✓ pipa, a színek vagy a jegyzet áthelyezése nem változtat rajta.",
    faq_q_note_written_at: "Hogyan látom, mikor írtam egy jegyzetet?",
    note_written_at: "Utoljára írva: {date}",
    faq_a_new_me_month: "A varázslatos hátizsákban → Havi naptár: minden nap színe azt mutatja, hány étkezés lett kipipálva, a ‹ › nyilakkal lehet hónapot váltani, a naptár alatt pedig a hónap napi átlagos kalóriája látszik. Egy napra koppintva látszik, hány étkezés lett kipipálva és hány kalória fogyott aznap.",
    faq_q_new_me_month: "Hol látom visszamenőleg a hónapot és az átlagos kalóriát a New Me-ben?",
    nm_month_avg: "Havi átlag: napi {kcal} kalória · rögzített napok: {n}",
    nm_month_day_empty: "Ezen a napon nem lett semmi rögzítve.",
    nm_month_day_line: "Kipipált étkezések: {checks} · kalória: {kcal}",
    nm_extra_line_small: "{n} kalória ehhez az étkezéshez a kis reggeliből – például {ideas}",
    faq_a_new_me_small_breakfast: "Könnyű reggeli (kb. 170 kcal): egy tönkölypita (legfeljebb 100 kcal) kenhető krémmel vagy sajttal, mellé egy zöldség – válassz legfeljebb 3 kedvencet, például 1 teáskanál csokikrémet, 1 teáskanál mogyoróvajat vagy egy szelet legfeljebb 22%-os sajtot. Mivel kicsi, egy másik időpontban jár mellé a „Plusz egy kis étkezés” (másfél órával később, például 11:30 → 13:00 – bármilyen más időpont is választható): még egy pita krémmel, fehérjejoghurt gyümölccsel, rizsszelet túróval, gabonapehely tejjel vagy fél pita tojással – legfeljebb kb. 200 kcal, saját ✓ jelöléssel. Ami még megmarad, az a többi étkezés között oszlik el, és mindegyik mutatja, mennyi jutott neki, így a nap összege a terv szerinti marad. Kiválaszthatod a kérdőívben, vagy 🔄-val csak mára válthatsz rá – például ha későn reggelizel.",
    faq_q_new_me_small_breakfast: "Mi az a „kis reggeli” a New Me menüben?",
