    weather_sky_snow: "Hó",
    weather_sky_storm: "Vihar",
    faq_a_ai_icon: "Igen – a Beállítások > Megjelenés és kijelző részben. Alapból a puha buborék, Premiummal pedig lebegő agyat vagy robotot is választhatsz.",
    faq_a_new_me_favorites: "Igen. A kérdőívben (és amikor a beállításokból újra kitöltöd) minden étkezéshez legfeljebb 2 lehetőséget választhatsz. Az első a menüben látszik, alatta egy „vagy” sor a másodikkal – rákoppintva csak mára arra váltasz. Ha pedig a reggeli nem fogyott el időben, a „⏰ Később” a nap későbbi részére teszi át, a kalória változása nélkül.",
    faq_a_theme_mode: "Néhány különleges téma sötétben a legszebb – Akvarell, Sarki fény, Barbie és a két csillámos téma –, ezért ha ezek közül választasz egyet, az app sötét módra vált, bármely más téma (a rakéta is) pedig világosra. A Fekete és a Sötétszürke sötét marad. Utána bármikor átválthatsz a menü 🌙 gombjával vagy a beállítások Világos Mód kapcsolójával.",
    faq_a_water_month: "A vízkövetésben. A mai napló minden bejegyzése mellett ott az idő, amikor hozzáadták, a „Havi táblázat” pedig megnyitja az egész hónapot: minden napnál látszik, hány liter fogyott (✓, ha meglett a napi cél), és egy napra koppintva megjelennek a bejegyzései időponttal.",
    faq_q_ai_icon: "Megváltoztathatom az MI-asszisztens ikonját?",
