    nm_times_same_kcal: "Bármit választasz, a nap kalóriája ugyanannyi marad: ami kimarad, az a többi étkezés között oszlik el.",
    dev_sim_panel_title: "PM – csak neked",
    faq_a_new_me_weight_optional: "Nem. A kérdőívben a jelenlegi és a céltestsúly is opcionális. Ha később mérés kerül be (⚖️ Testsúly a New Me „Az utam” részében vagy a testsúlynaplóban), a haladás az elsőtől számít.",
    faq_q_new_me_weight_optional: "Kötelező megadni a testsúlyt a New Me-ben?",
    nm_unlock_desc: "A menüd, a kihívások és az út készen állnak – lépésről lépésre, együtt.",
    nm_unlock_title: "A New Me feloldva!",
    room_reveal_star: "Új csillag gyúlt ki a tetőn álló távcsőben ✨",
    faq_a_room_records: "A lemezjátszó kezdettől a szobában áll, a fotel melletti fatönkön. A lemezei a YouTube-on megnyitják az elmúlt évek nagy slágereinek hivatalos klipjeit, alattuk pedig öt nyugodt dallam szól itt, a szobában – a lemez forog, amíg szólnak, és a „⏹ Leállítás” kikapcsolja a zenét.",
    faq_a_room_roof_gifts: "A 8. kulccsal érkeznek. A távcsőre koppintva át lehet nézni rajta: az éjszakai égbolt közelről – húzd (vagy használd a nyilakat), hogy körülnézz – és a befejezett kihívásaid csillagképet rajzolnak benne, minden kihívásért egy csillag; egy csillagra koppintva látszik, melyik volt. A kis ládára koppintva kinyílik – egyelőre üres – még egy koppintás pedig bezárja.",
    faq_q_room_records: "Mi van a lemezjátszón a titkos szobában?",
    faq_q_room_roof_gifts: "Mi a távcső és a láda a tetőn?",
    room_chest_letter: "Egy kis levél neked",
    room_chest_letter_1: "Az út minden kis lépése valódi volt – és mindegyik számít.",
    room_chest_letter_2: "Kedvesnek lenni önmagunkhoz az út része, nem szünet belőle.",
    room_chest_letter_3: "Vannak könnyebb és nehezebb napok. Mindkettőben ott lenni – ez az igazi erő.",
    room_chest_letter_4: "Szabad pihenni. A pihenés is egy lépés előre.",
    room_chest_letter_5: "A maradandó változások a csendesek – napról napra épülnek.",
    room_chest_letter_6: "Ma jó nap arra, hogy büszkeséget érezz – ha csak egy kicsit is.",
    room_chest_letter_7: "Nem kell mindent megcsinálni. Csak a következő kis dolgot.",
