    dev_sim_buy: "Mintha megvetted volna – nézd meg, hogyan nyílik meg minden",
    dev_sim_lock: "Zárolás – úgy látni, mint vásárlás előtt",
    dev_sim_locked_toast: "🔒 Zárolva – vásárlás előtt így néz ki",
    faq_a_new_me_preview: "Igen. A New Me oldala egy rövid videóval kezdődik arról, mi történik benne: a kérdőív, a folyosó lámpái, a hátizsák, a kihívások és a kulcsok. Alatta minden ott van, ami benne van, egy nap előnézete és rövid válaszok.",
    faq_q_new_me_preview: "Megnézhetem a New Me-t vásárlás előtt?",
    nm_trailer_c1: "Egy rövid kérdőív – és kész a menüd",
    nm_trailer_c2: "Minden étkezés egy lámpa a folyosódon",
