    nm_trailer_replay: "Újra megnézem",
    ai_chat_food_edit: "✏️ Kalória / fehérje javítása",
    ai_chat_food_invalid: "A kalóriának 0-nál nagyobb számnak kell lennie",
    ai_chat_food_updated: "Frissítve:",
    faq_a_ai_chat_food_fix: "Igen. A csevegésben a válasz alatt koppints a ✏️ Kalória / fehérje javítása gombra, írd át a számokat, és koppints a Mentésre. Csak az változik, amit most adtál hozzá – akkor is, ha egy már meglévő nassoláshoz került. Az AI hibázhat, ezért érdemes gyorsan ránézni.",
    faq_a_new_me_home_btn: "Ha van New Me-d, a kezdőképernyő tetején, a fókusz mód mellett egy kis 💎 nyitja meg a mai menüt. A mai étkezések A Napomban is látszanak, mindegyik ✓-val.",
    faq_a_routine_item_days: "Igen. Koppints az elemre a Rutinomban, és válaszd ki a napjait a 📅 Napok alatt – például csak hétfőtől péntekig. A többi napon nem jelenik meg A Napomban, és nincs ✓-ja; a Rutinomban halványabban ott marad, mellette a napjaival. A kártya, amely 3 ✓ nélküli nap után rákérdez egy elemre, csak az elem saját napjait számolja.",
    faq_q_ai_chat_food_fix: "Javítható a kalória vagy a fehérje, miután az asszisztens rögzítette az ételt?",
    faq_q_new_me_home_btn: "Hol van a New Me a kezdőképernyőn?",
    faq_q_routine_item_days: "Lehet egy Rutinom-beli elem csak bizonyos napokon?",
    routine_item_days_label: "📅 Napok",
    home_note_meal_ph: "Mentett étkezés keresése…",
    menu_quick_search: "Gyors keresés",
    nm_times_hint: "Tipp: beállíthatod azt a legkésőbbi időpontot, amikor az adott étkezést általában eszed – például 9:00-t, ha gyakran 8 körül eszel.",
    room_game_marquee: "Útközben – állj meg, és élvezd",
    room_sand_erase_aria: "Dörzsöld le az írást",
    faq_a_home_note_line: "Írj a kezdőképernyő közepén lévő sorba, és koppints a ➤ gombra (vagy Enter) – a Jegyzetek közé kerül. Koppints a sor elején lévő 📝-re, és 🛒 lesz belőle: ekkor amit írsz, a Bevásárlólistára kerül. Még egy koppintás, és 🍎 lesz: írj be pár betűt, megjelennek a hozzá illő mentett étkezések, és egy koppintással egyet a mai étkezések közé írsz. 🎤 segítségével egyszerűen ki is mondhatod.",
    faq_a_night_mode: "Nyisd meg a menüt ☰, és koppints fent a 🌙-ra – az egész app sötét lesz. Ugyanott a ☀️ visszahozza a nappalt. A Beállításokban is megtalálod, a Világos Mód alatt.",
    faq_q_home_note_line: "Hogyan írok gyors jegyzetet a kezdőképernyőről?",
    faq_q_night_mode: "Hogyan válthatok éjszakai módra?",
    menu_day_mode: "Nappali mód",
    menu_night_mode: "Éjszakai mód",
    faq_a_secret_room_yoga: "Az erdei ösvény végén egy ragyogó kapu áll, mögötte pedig, egy vízesés mellett, az erdei lények – Lumi, Puffi, Nixie és Sparklet – félkörben ülnek a szőnyegükön, Flora, a jógatanárnő pedig velük szemben ül a kövön lévő magányos szőnyegen. Koppints Florára: kinyitja a szemét, minden közelebb jön, és a beszélgetés lassan, olvasásra hagyott idővel kezdődik – Flora megkérdezi, hogy van mindenki, minden lény a saját neve alatt válaszol (minden sor mellett egy kis képpel arról, aki éppen beszél), aztán tőled kérdezi meg, hogy érzed magad a hozzád közel álló emberekkel. A beszélgetés a válaszaid szerint folytatódik – jó emberek, valaki, akivel nehéz, vagy egy kis magány. Minden út egy kis küldetéssel (rögtön bekerülhet A Napomba; ha a küldetés az, hogy írj valamit, van hely az írásra, és a varázslatos naplóba mentődik) és egy pózzal ér véget, három közös lélegzettel. A ↩ egy lépést visszalép, a ✦ új beszélgetést kezd. A következő kulcs megnyitja a vízesést: ha leülsz a kőre, minden eltűnik, és csak a víz hangja marad. Ha a tó fölé hajolsz, egy kérdés emelkedik ki a vízből – mit tenne ma az igazi éned? – és a válasz egy kis feladat lesz A Napomban. Ez egy kedves pillanat, nem helyettesíti a szakemberrel való beszélgetést.",
    faq_q_secret_room_yoga: "Mi történik az erdei jógán?",
