    room_waterfall_rock_aria: "Leülés a sziklára",
    room_yoga_guide_aria: "Beszélgetés Florával",
    yg_g_alone: "Köszönöm, hogy megosztottad. Néha mindenkivel megesik.",
    yg_g_alone_q: "Mi esne jól, akár csak egy kicsit is?",
    yg_g_critic: "A kritika sokáig tud szúrni. Egy pillanatról szól – nem az egész emberről.",
    yg_g_end: "Köszönöm, hogy eljöttél a körbe. Bármikor visszajöhetsz.",
    yg_g_gate: "Szabad határt húzni. A határ nem fal – hanem kapu.",
    yg_g_good: "De szép 💛 Ki tett jót veled ezen a héten?",
    yg_g_good_msg: "A jó embereknek érdemes elmondani, hogy jók. Egy kis köszönöm az egész napjukat feldobhatja.",
    yg_g_hard: "Köszönöm, hogy elmondtad. Mi nyom a legjobban?",
    yg_g_listen: "Fárasztó, ha nem hallanak meg. A hangod számít, akkor is, ha halk.",
    yg_g_new: "Az új emberek egy kis hellóval kezdődnek. Egy tanfolyam, egy séta, egy csoport – egy lépés.",
    yg_g_old: "Aki már ismer, az egy meleg hely. Elég egy rövid üzenet.",
    yg_g_start: "És most te jössz 🌿 Hogy érzed magad mostanában a hozzád közel álló emberekkel?",
