    nm_time_hour: "Óra",
    nm_time_minutes: "Perc",
    routine_time_taken: "Erre az időpontra már van valami: {title}",
    faq_a_new_me_times: "A kezdő kérdőívben, és bármikor a New Me beállításaiban → „Étkezési időpontok”. Ha a rutinodban már vannak étkezési időpontok, onnan kerülnek át – és a rutin étkezései elrejthetők, a helyükön pedig a New Me étkezései jelennek meg. Ha nincsenek, kiválasztod, hány étkezés legyen naponta (2 étkezés + egy nasi / 2 étkezés + egy könnyű vacsora / 2 étkezés + egy nasi + egy könnyű vacsora), és mikor legyen mindegyik. A „2 étkezés + egy nasi” esetén ez ebéd 11:30-kor, nasi 16:00-kor és vacsora 19:00-kor (bármelyik módosítható). Ezek az étkezési időpontjaid mindenhol: a folyosón, A Napomban, a Rutinomban és az emlékeztetőkben. Bármit választasz, a nap kalóriája ugyanannyi marad – ami kimarad, az a többi étkezés között oszlik el.",
    faq_q_new_me_times: "Hogyan állítom be az étkezési időpontjaimat a New Me-ben?",
    nm_times_count: "Hány étkezés naponta?",
    nm_times_from_routine: "Igen, vedd át a rutinomból",
    nm_times_hide: "A rutinom étkezései helyett a New Me étkezései jelenjenek meg",
    nm_times_later: "Később",
    nm_times_manual: "Nem, itt választok",
    nm_times_none_found: "A rutinodban még nincs étkezés – válaszd ki itt, hányszor és mikor.",
    nm_times_q: "Vannak a rutinodban állandó étkezési időpontok?",
    nm_times_saved: "Az étkezési időpontok elmentve",
    nm_times_title: "Étkezési időpontok",
    faq_a_routine_exact_time: "Igen. Ha pontos időponttal írod le a rutint az MI-nek (például „16:10 trading”), pontosan így mentődik el – nem kerekítődik egész órára. Minden, ami a rutinodban szerepel, mindig látszik a táblán, akkor is, ha az órája nincs kiválasztva az órabeállításokban, és ha olyan órát veszel ki, amelyben van valami, előbb rákérdez. Az időpontot kézzel is módosíthatod: koppints az időpontra az elem ablakában, és válaszd ki az órát és a percet.",
    faq_q_routine_exact_time: "Lehet a rutinomban pontos időpont, például 16:10?",
