    routine_daysoff_what: "És mi a rutin ezeken a napokon?",
    routine_daysoff_which: "Mely napok?",
    faq_a_secret_room_diary: "Csak te. A napló oldalai a fiókodba mentődnek, így minden eszközön ott vannak, és senki más nem látja őket. A titkos szoba íróasztalán lévő varázslatos napló megnyitja, és a zenesarokban lévő napló is. Az új oldal alatt egy összecsukott havi táblázat van: pötty jelöl minden napot, amelyiken van oldal, egy napra koppintva pedig megnyílnak az oldalai – ott egy oldal törölhető is. Ha a napló már nyitva van, a főmenübe is felvehető – a naplóban lévő kapcsolóval vagy a New Me beállításaiban.",
    faq_a_secret_room_places: "Az erdőkapu minden bejárata a saját kulcsával nyílik. Mögöttük: a tengerre néző veranda (a kis asztalon Aladdin lámpása – egy koppintás, és egy erdei szellem száll fel belőle varázslatos ködben, körbekavarog, és beszélgetést kezd a kívánságodról – lásd: „Mit csinál a lámpa szelleme?”), a gitár és a napló (a gitár rövid, nyugodt dallamot játszik, és magától elhallgat, a fán lógó három lemez mindegyike pedig a saját varázslatos dallamát játssza – újabb koppintásra elhallgat –, a fatönkön lévő naplóba pedig írni lehet), a lélegzés szobája (csendes tó naplementében – a vízen egy lótuszlámpás lebeg: koppints rá, írj egy kívánságot, és az elúszik vele, messze vissza a tóba; a varázspálcával a homokba írhatod, amit el szeretnél engedni, és ott marad, amíg az ujjaddal le nem törlöd) és az erdei ösvény (éjszaka nyílik meg, a lámpások megérintése pedig nappalra vált; a padon le lehet ülni, a tábla megérintése pedig közel hozza – egy tábla hat kis kérdéssel, amelyeket ki lehet pipálni). A zárt bejáraton látszik, hány kulcs van még hátra. Az ösvény végén egy ragyogó kapu a vízesés melletti jógához vezet – onnan pedig magához a vízeséshez.",
    faq_q_secret_room_diary: "Ki látja a naplót?",
