    ai_chat_sub: "Itt vagyok neked",
    ai_chat_title: "Asszisztens",
    ai_chat_tool_food: "🍎 Amit ettem",
    ai_chat_tool_photo: "📷 Recept fotója",
    ai_chat_tool_schedule: "📅 Valami a naptárba",
    ai_chat_tool_table: "🗂️ Új táblázat",
    ai_chat_working_food: "Egy pillanat, számolom a kalóriákat…",
    ai_chat_working_schedule: "Egy pillanat, beírom a naptárba…",
    ai_chat_working_table: "Egy pillanat, készítem a táblázatot…",
    dev_weather_preview_label: "Előnézet – csak a te fiókodban:",
    faq_a_ai_chat: "Koppints a buborékra, és megnyílik egy csevegés. Válaszd ki, mit szeretnél – valamit a naptárba, amit ettél, egy recept fotóját vagy egy új táblázatot –, vagy csak írj, és az asszisztens magától megérti. A 🎙️-ra koppintva gépelés helyett beszélhetsz is. A naptárnál választhatod, hogy egyszer, minden héten vagy minden nap. A válasz a csevegésben érkezik, onnan pedig továbbléphetsz valami másra, vagy megnyithatod a naptárt / amit ettél.",
    faq_a_new_me_hall: "A New Me egy varázslatos erdő kapujánál kezdődik, és benne minden bejárat egy hely: az óriásfa kerek ajtaja a titkos szobába vezet, az odvas farönk a tengerre néző verandára, a gombaház a gitárhoz és a naplóhoz, a kis fűzfaív a lélegzés szobájába, a nagy fűzfaív az erdei ösvényre, a létrás virágív pedig felvisz a csillagtetőre, amint az megnyílik. A zárt bejáraton lakat van. Az ösvényen lebeg a karaktered, Sky, körülötte pedig a játék gombjai: a következő küldetés, a hét kihívása, a varázslatos hátizsák az egész New Me-vel, a világtérkép és az eszközök. A fenti kulcsokra koppintva kiderül, hogyan lehet kulcsokat szerezni.",
    faq_a_new_me_routine_meals: "Ha a New Me-ben be vannak állítva étkezések, és a Rutinomban is vannak étkezések, a New Me megkérdezi, elrejtse-e őket, és a helyükön a New Me étkezései jelenjenek-e meg – hogy semmi ne látszódjon kétszer. A Rutinom ezután a New Me étkezéseit mutatja a saját időpontjukban, 💎 és ✓ jellel (egy étkezés nevére koppintva megnyílik egy ablak egy másik étkezés kiválasztásához vagy az időpontja módosításához, rögtön ott a rutin fölött). Semmi sem törlődik: visszajönnek a New Me ⚙️ Beállításai → Étkezések a rutinban pontjában, vagy ha kikapcsolod a „Szinkronizálás a New Me-vel” kapcsolót a Rutinom ⚙️ menüjében. Aktív New Me nélkül maguktól visszatérnek.",
    faq_a_room_computer: "Ez egy kis csevegés, amely azzal kezdődik: „Hogy telik eddig a napod?” – jól, zsúfoltan vagy nehezen –, és lépésről lépésre veled folytatódik, egészen egy kis küldetésig a végén (ami egyenesen A Napomba is mehet). A válaszokra koppintani lehet, vagy szabadon beírni őket – a beírt szöveg a legközelebbi válaszhoz kapcsolódik. A „↩ Vissza” egy lépést visszalép, hogy másképp válaszolhass, az „Új csevegés” pedig bármikor újrakezdi. Egy zsúfolt vagy nehéz nap után később ugyanazon a napon visszatérhetsz a számítógéphez: a „Visszajöttem...” folytatja a beszélgetést. A lenti zöld fény ki- és bekapcsolja a számítógépet. Csak a választások maradnak meg, csak ezen az eszközön és csak a nap végéig.",
    faq_q_ai_chat: "Hogyan beszélhetek az asszisztenssel?",
    faq_q_new_me_hall: "Mi a folyosó a New Me-ben?",
    faq_q_new_me_routine_meals: "Miért a New Me étkezései látszanak a Rutinomban?",
    faq_q_room_computer: "Hogyan működik a számítógép a titkos szobában?",
