    nm_late_change: "Módosítás",
    nm_late_drink: "🍵 Csak egy ital",
    nm_late_eat: "🍎 Valami kis harapnivaló",
    nm_late_none: "🌙 Semmi",
    nm_late_rem_drink_body: "Tea, gyógytea vagy víz – zárd nyugodtan a napot 🍵",
