    recipes_search_placeholder: "Recept vagy hozzávaló keresése…",
    dictation_btn_aria: "Beszélj, és leírja",
    dictation_mic_denied: "A mikrofon le van tiltva – engedélyezd a böngészőben a cím melletti 🔒 ikonnál vagy a telefon beállításaiban",
    faq_a_dictation: "Igen – koppints a 🎤 mikrofonra a gyors jegyzet vagy egy füzetbeli írólap sarkában, és beszélj: a szavak beszéd közben íródnak le, az app nyelvén. Újabb koppintással leáll. Első alkalommal a böngésző engedélyt kér a mikrofonhoz. Működik a Chrome / Android rendszeren és az iPhone Safari böngészőjében. Számítógépen mikrofon és egy olyan böngésző kell, mint a Chrome, az Edge vagy a Safari – ha valami hiányzik, az üzenet pontosan megmondja, mi.",
    faq_q_dictation: "Beszélhetek gépelés helyett?",
    faq_a_secret_room: "Egy szoba, ami csak a tiéd, a New Me-ben – egy ház egy óriásfa belsejében. Egyszerre egy falat látsz, és a nyilakkal (vagy húzással) fordulsz. Az első kulcs azután jön, hogy 3 különböző napon ✓ került egy étkezésre, és kinyitja az ajtót – vele együtt az egész szobát: a számítógépet, a játékot, a lemezjátszót, a polcot a könyvtárral és a macskát. Utána minden befejezett kihívás (a hét kihívása is) ad egy kulcsot, ami megnyitja a következő helyet: a csillagtetőt, a tengerre néző verandát, a gitárt és a naplót, a lélegzés szobáját, az erdei ösvényt a jógával, a vízesést és egy meglepetést a tetőn – a 8. pedig egy palackot hoz a tengerből, benne a múltból jött levéllel. Amikor valami kinyílik, egy nyíl mutatja az utat. A játékgép alján lévő kis ajtó is kinyílik – a mögötte lévő szekrény egyelőre üres. A csillagtetőn a megérintett csillag hullócsillagként zuhan, a macska pedig a párnán ül.",
    faq_q_secret_room: "Mi a titkos szoba a New Me-ben?",
