    room_wall_shelf_hint: "Könyvek, füzetek és emlékek · az ajtó a tetőre vezet",
    room_wall_shelf_title: "A polc és a következő ajtó",
    room_wall_window_hint: "Koppints egy tárgyra, hogy közelebb menj · a nyilak forgatják a szobát",
    room_wall_window_title: "Az ablak és a számítógép",
    faq_a_steps_in_sport: "Az Edzéskövetés tetején, egy kis sávban: a mai és az e heti lépések. A lépések maguktól számolódnak majd, amint az app a telefonos verzióban összekapcsolódik a Google Fit / Apple Health szolgáltatással – a mellette lévő 🔗 gomb elmagyarázza.",
    faq_q_steps_in_sport: "Hol van a napi lépésszámláló?",
    sport_steps_today_label: "lépés ma",
    sport_steps_week_label: "ezen a héten",
    faq_a_reminders_one_place: "Minden emlékeztető egyszer és egy helyre érkezik. Ha az app előtted van nyitva (a számítógépen, az iPaden vagy a telefonon), ott jelenik meg; különben értesítésként csak a telefonra jön. A '✅ Kész, köszönöm!' vagy az 'Értem!' bárhol bezárja minden eszközön, és nem jön vissza. A 'Még nem' elhalasztja: 5 percenként visszajön, minden alkalommal egy helyre. Ha a listában ✓-val kipipálod a feladatot, az is késznek számít. Ha az értesítéseket számítógépen és táblagépen is szeretnéd megkapni, kapcsold be a 'Számítógépen és táblagépen is' lehetőséget a Beállítások > Értesítések alatt.",
    faq_q_reminders_one_place: "Miért csak egyszer és csak a telefonra érkezik egy emlékeztető?",
    reminder_all_devices_hint: "Alapértelmezés szerint minden emlékeztető egyszer és egy helyre érkezik: a telefonra, vagy arra az eszközre, ahol az app éppen előtted van nyitva. A Kész vagy az Értem egy helyen mindenhol bezárja.",
    reminder_all_devices_label: "Számítógépen és táblagépen is",
    myday_water_info: "8 közepes / kis pohár víz átlagosan körülbelül 2 liter",
    faq_a_good_things: "Este (18:00-tól) egy kis gomb jelenik meg a dátum alatt: írj le legfeljebb 3 jó dolgot, ami ma történt – már egy is elég. Elmentődnek, és a „Korábbi napok” alatt látod, mit írtál korábban. A „Ma este nem” holnapig elrejti, teljesen pedig a Beállítások > Személyre szabás és naptár részben kapcsolhatod ki.",
    faq_a_home_countdown: "Jelölj meg egy eseményt ⭐-gal a naptárban (a csillag mellette az eseménylistában). A következő 100 napban a legközelebbi megjelölt esemény a dátum alatt jelenik meg – „Még 3 nap · Anya születésnapja”, „Holnap · …” vagy „Ma · …”. Koppints rá, és a naptárban arra a napra ugrasz.",
    faq_a_home_streak: "Azt számolja, hány egymást követő napon volt legalább egy ✓ – bármi a Napomban, a Rutinomban, a Céljaimban vagy a New Me-ben. 2 naptól jelenik meg. Ha ma még nincs ✓, a sorozat nem szakadt meg – még előtted az egész nap. Ha pedig véget ér, egyszerűen csendben eltűnik, bűntudat nélkül.",
    faq_a_home_weather: "Kapcsold be az „Időjárás a kezdőképernyő égboltján” opciót a Beállítások > Személyre szabás és naptár részben, és engedélyezd a helyet. Ezután a kezdőképernyő égboltja az igazi időjárást mutatja ott, ahol vagy – napot (éjjel holdat és csillagokat), felhőket, esőt, havat, vihart vagy ködöt – minden témában, nagyjából 40 percenként frissülve. A hozzávetőleges helyed (kb. 1 km-re kerekítve) csak az eszközödön marad, és a szerverünkön keresztül ellenőrizzük a MET Norway-nél. Alapértelmezés szerint ki van kapcsolva. A kapcsoló alatt látszik, milyen most kint az idő – például ⛅ Részben felhős, ezért van az égen nap és felhő is.",
    faq_q_good_things: "Mi az a „3 jó dolog a mai napból”?",
    faq_q_home_countdown: "Hogyan kapok visszaszámlálást a kezdőképernyőre?",
    faq_q_home_streak: "Mi az a 🔥 „nap egymás után” a köszöntés alatt?",
    faq_q_home_weather: "Hogyan kapom meg az időjárást a kezdőképernyő égboltján?",
    good_things_chip: "3 jó dolog a mai napból",
    good_things_chip_done: "3 jó dolog ✓",
    good_things_hint: "Valami apróság, ami ma jó volt – már egy is elég.",
    good_things_past: "Korábbi napok",
    good_things_past_empty: "A korábbi napok itt jelennek meg.",
    good_things_placeholder: "Valami jó, ami történt…",
    good_things_saved_toast: "Mentve. Jó éjszakát 🌙",
    good_things_skip: "Ma este nem",
    good_things_title: "3 jó dolog a mai napból",
    home_countdown_days: "Még {n} nap · {title}",
    home_countdown_today: "Ma · {title}",
    home_countdown_tomorrow: "Holnap · {title}",
    home_streak_days: "{n} nap egymás után",
    home_streak_title: "Egymást követő napok legalább egy ✓-val",
    settings_good_things_label: "„3 jó dolog” esténként",
    settings_weather_hint: "Eső, felhők vagy hó a kezdőképernyő hátterében, az ottani időjárás szerint, ahol vagy. A hozzávetőleges helyed ezen az eszközön marad, és a szerverünkön keresztül ellenőrizzük a MET Norway-nél.",
    settings_weather_label: "Időjárás a kezdőképernyő égboltján",
    weather_failed: "Most nem sikerült lekérdezni az időjárást.",
    weather_location_denied: "Nincs hozzáférés a helyhez – engedélyezd a böngésző beállításaiban, és próbáld újra.",
    faq_a_home_focus: "Koppints a ◎-ra a kezdőképernyő tetején: minden eltűnik, kivéve az egyetlen mostani dolgot – ami ebben az órában van, vagy a mai lista következő tételét – egy nagy ✓-val, plusz a Gyors Jegyzet. A ✓ után megjelenik a következő. Koppints a „Fókusz mód ✕”-re felül, és minden visszajön.",
    faq_a_home_search: "Nyisd meg a menüt ☰ – a keresés legfelül van. Írj be legalább 2 betűt: a találatok a jegyzeteidből, a bevásárlólistából, a naptárból, a receptekből, a füzetekből (címek és oldalszöveg), a célokból, a táblázatokból és a könyvekből jönnek, típus szerint csoportosítva – koppints egyre, és egyenesen oda ugrasz.",
    faq_a_my_day: "A Napom egyetlen idővonalon egyesíti azt, ami korábban az Egy Pillantás a Mai Napra és a Rutinom volt. A kezdőképernyő alján látod, mennyi van kész, mi van most vagy mi következik (gyors ✓-val), a cím mellett pedig egy pohár vizet +1-gyel. Koppints rá (vagy húzd felfelé), és megnyílik az egész nap: felül, aminek nincs időpontja, utána minden óránként – a naptár feladatai, eseményei és találkozói, a heti fix idősávok, a mai rutin, a céljaid kis lépései és a New Me étkezései – egy vonallal a mostnak. Szűrhetsz Feladatok, Rutin vagy Találkozók és események szerint. Az itteni ✓ ugyanaz a ✓, mint mindenhol máshol (Rutinom, Céljaim, naptár), és kinyit egy százszorszépet a sarokban. A „Rutin szerkesztése” megnyitja a Rutinomat (a menüben is megvan), a „＋ Hozzáadás mára” pedig felvesz egy feladatot mára. Az „A Napom” címre (vagy a fenti kis csíkra) koppintva újra bezárul.",
    faq_q_home_focus: "Mi az a fókusz mód?",
    faq_q_home_search: "Hogyan kereshetek az egész appban?",
    faq_q_my_day: "Mi van a Napomban a kezdőképernyő alján?",
