    nm_plan_life: "Örökre",
    faq_a_new_me_tour: "Közvetlenül a vásárlás és a rövid kérdőív kitöltése után egy rövid bemutató megmutatja a játékot: a felső sávot, a következő küldetést, a hét kihívását, a varázslatos hátizsákot és az 1-es ajtót a titkos szobába. Bármikor újra lejátszható a ⚙️ Beállítások > 🧭 New Me bemutató pontban – ott a kérdőívben megadott teljes név is módosítható. Vásárlás előtt a New Me mellett 🔒 látszik a menüben, és rákoppintva megnyílik egy oldal mindazzal, amit tartalmaz.",
    faq_q_new_me_tour: "Van útmutató a New Me-hez?",
