    nm_tour_done_title: "Indulhatunk 💪",
    nm_tour_tiles_text: "Az út és a kitüntetések, bevásárlólista, testméretek, fotók, havi naptár, emlékeztetők és a menü PDF-je.",
    nm_tour_tiles_title: "Minden más",
    nm_tour_challenges_text: "20 kihívás közül lehet választani, és akkor indul, amikor eldöntöd – a végén pedig ajándék vár.",
    nm_tour_drinks_text: "Kávé, tea vagy bármi más – a kalóriák automatikusan számolódnak. Koppints a megnyitáshoz.",
    nm_tour_swap_text: "🔄 lecserél egy étkezést – a menüből, a mentettek közül vagy AI-jal írva, mára vagy mostantól. ⭐ elmenti, ➖ kiveszi a menüből.",
    nm_tour_menu_text: "A mai étkezések. ✓, amikor egy étkezés megvolt – magától bekerül a Napi Étkezéskövetőbe.",
    nm_tour_ring_text: "A gyűrű mutatja, mennyi maradt ma a tervből. Az edzések hozzáadódnak.",
