    nm_gift_intro: "Mind a(z) {n} kihívás, lépésről lépésre. Ez várt rád:",
    nm_gift_title: "Az ajándékod",
    faq_a_new_me_letter_gift: "A New Me elején (vagy később, a Kihívásoknál) levelet lehet írni a jövőbeli önmagadnak. Lepecsételés után nem olvasható és nem szerkeszthető, amíg ki nem nyílik: a tengerből jött palackban a titkos szobában, vagy mind a 20 kihívás végén – ahol ajándék is vár.",
    faq_q_new_me_letter_gift: "Mi az a levél a múltból?",
    faq_a_new_me_challenges: "A 🏆 Kihívások 20 kihívást tartalmaz: 10 nagyot (például 5 nap cukor nélkül, egy hét szénhidrát nélkül vagy 4 kg mínusz egy hónap alatt – minden nap kalóriadeficit, edzés és cukor nélkül) és 10 minit – egyhetes apró szokásokat, mint a fahéjas kávé cukor nélkül. Kihívás választásakor a kérdés az, mikor kezdődjön: ma, holnap, jövő héten vagy más napon. Egy nagy és egy mini kihívás futhat egyszerre. A futó kihívás a menü tetején és a Napom részben jelenik meg, a napi ✓-vel. A kihívás minden hetére jár egy szabadnap (🍕), amely nem szakítja meg, a ki nem pipált nap pedig szabadnapnak számít – a mai és a tegnapi nap is kipipálható. Egyes napok maguktól kipipálódnak: egy 20 perces edzés az Edzéskövetésben, vagy a menü ✓-es étkezései. Minden kihívásnál van egy ⓘ arról, hogy pontosan mi számít bele (például a szénhidrátok teljes listája) – magában a kihívásban és mellette a Napom részben. Alattuk a 🌱 Személyes fejlődés 48 apró, egyhetes kihívást kínál (ezek nem számítanak bele a 20-ba) – lásd: „Mi a hét kihívása?”.",
    faq_q_new_me_challenges: "Hogyan működnek a kihívások a New Me-ben?",
    nm_letter_too_short: "Még néhány szó 🙂",
    nm_letter_quiz_note: "Nem kötelező – később is megírható a Kihívások részben.",
    nm_letter_write: "✍️ Levél írása",
