    nm_letter_seal_note: "Lepecsételés után a levél nem olvasható és nem szerkeszthető, amíg minden kihívás nem teljesül.",
    nm_letter_seal: "✉️ Levél lepecsételése",
    nm_letter_ph: "Hol tartok ma, hová szeretnék eljutni, mi nehéz nekem az evéssel kapcsolatban, mit mondanék magamnak a célban…",
