    nm_tile_challenges: "Kihívások",
    faq_a_workout_calories: "Igen. Minden edzéshez becslés készül az elégetett kalóriáról – a típus, az időtartam és a legutóbbi testsúlyod alapján (futásnál és kerékpározásnál a sebesség alapján is, ha megadtad a távot). Megjelenik az edzéslistában és a havi összesítőben (Elégetett), és hozzáadódik az aznapi kalóriakerethez: a Napi Étkezéskövetőben, a Kalória- és testsúlymutatókban és a New Me gyűrűjében. Ez becslés, ezért ~ jellel látszik.",
    faq_q_workout_calories: "Beleszámítanak az edzések a napi kalóriáimba?",
    faq_a_new_me_flexible_menu: "Igen. A kérdőívben és a beállításokban választható, hány étkezés legyen naponta – 2 étkezés + egy nasi / 2 étkezés + egy könnyű vacsora / 2 étkezés + egy nasi + egy könnyű vacsora –, és az étkezés kártyáján a ➖ kiveszi (legalább 3 marad); a „➕ Vissza a menübe” visszahozza. Mindenképp ugyanannyi marad a nap kalóriája: ami kimarad, az a többi étkezés között oszlik el, és minden étkezés alatt látszik, mennyi jött hozzá és mi illik mellé. Az étkezésen a ✏️ Szerkesztés megnyitja a szövegét – változtass rajta tetszés szerint (pl. kenyér nélkül vagy még egy tojással), és az AI újraszámolja a kalóriát és a fehérjét. A 🔄 Csere lehetőségeket kínál a menüből, a ⭐ Mentett és a ✨ Megírom fülön; minden változtatás szólhat csak mára vagy mostantól. Az „Az egész nap” végén pedig ott a ➕ Étel hozzáadása – írd le, mit ettél a menün kívül, és az AI kiszámolja és hozzáadja a mai naphoz (✕ törli).",
    faq_q_new_me_flexible_menu: "Megváltoztathatom az étkezések számát a New Me-ben, vagy ehetek saját ételt?",
