    nm_restore_meal: "Vissza a menübe: {slot}",
    nm_room_hint: "Egy kisebb választásból. Átkerülhetnek egy nagyobb étkezésbe, egy mentett ételbe vagy valamibe, amit az AI-jal írtál – koppints egy étkezésre a kitöltéshez.",
    nm_room_title: "Ma ~{n} kcal szabad",
