    nm_custom_from_saved: "A mentett ételeidből",
    nm_custom_from_ai: "AI-jal írva",
    nm_burned_line: "{n} kcal edzésből – hozzáadva a mai kerethez",
    faq_a_calendar_goals_reading: "Igen. Ha a Havi Áttekintésben egy napra koppintasz, egy külön „🎯 Célok és olvasás” csoportban az aznapi feladatok is megjelennek a céljaidból és könyveidből: egy napi kihívás napi feladatai, mérlegelési vagy számolási emlékeztetők és „📖 Olvass el N oldalt”. A maiakat ott helyben ki lehet pipálni, mint a Napom részben; a többi nap csak megtekintésre szolgál – az elmúlt napok megmutatják, mi készült el és hány oldalt olvastál, a következők pedig, hogy mi van tervezve. Hogy a naptár áttekinthető maradjon, csak a különleges napok kapnak kis jelet: 🎯 egy cél dátumán és 📖 azon a napon, amikorra egy könyvet be kell fejezni.",
    faq_q_calendar_goals_reading: "A célok és az olvasás a Havi Áttekintésben is megjelennek?",
    faq_a_meetings: "Koppints a ＋ gombra a Naptárnézetben (a Havi Áttekintésben, az Összes Eseménynél vagy a Találkozóknál), és válaszd fent a 🤝 Találkozó lehetőséget – a ✅ Feladat és a 📅 Esemény mellett, amelyek a régi módon működnek. A találkozónak van kezdési ideje, és ha szeretnéd, befejezési ideje, hogy kivel van, helyszíne vagy linkje (cím, Zoom, Meet…) és jegyzetei. A találkozók a 🤝 Találkozók kártyán jelennek meg – a hét papírnaptárában, minden napnak egy sorral; a nyilak hetet váltanak, egy találkozóra koppintva pedig szerkesztésre nyílik meg. A helyszín térképen nyílik meg, a hívás linkje pedig „🔗 Csatlakozás” gombot kap. A találkozók a Havi Áttekintésben és a Napom részben is látszanak az időpontjukkal, emlékeztetőt kapnak, mint bármely esemény, és a befejezési idővel, helyszínnel és részletekkel együtt szinkronizálódnak a Google Calendarral. A Napom nézetben egy megbeszélés azt is mutatja, kivel van (👤), és egy ismétlődő megbeszélés akár csak 1 hónapig is tarthat.",
    faq_q_meetings: "Hogyan adhatok hozzá találkozót, és hol látom a találkozóimat?",
