    faq_a_goal_tasks_peek: "Háromféle: egy aktív napi kihívás mindennapi feladatai (például „Szénhidrát nélkül”) – minden nap megjelennek a kihívás teljesítéséig, és az ottani ✓ a célban is kipipálja a napot (és fordítva); 📅 a célok általad ütemezett mérföldkövei – a saját napjukon, és a naptárban is; valamint 👣 bármely más cél kis lépése – a cél hozzáadásakor vagy szerkesztésekor állíthatod be (minden napra, vagy hetente egy általad választott napra). Ezek ugyanazok a lépések, mint „A mai kis lépések” a Céljaim tetején, mindegyik a saját céljának ikonjával. Az aznap rögzített +1 automatikusan kipipálja a kis lépést (és a testsúlymérés is, ha a kis lépés maga a mérés).",
