    faq_a_goal_days_challenge: "A Céljaim oldalon koppints a ＋ gombra (vagy a kész „🔥 8 nap” példára), válaszd a „📆 Napi kihívás” lehetőséget, add meg a napok számát, és add hozzá, mit csinálsz minden nap (pl. „30 perc séta”, „A menüm szerint enni”). Minden nap pipáld ki az adott nap feladatait a kihívás ösvénye alatt – ha mind ki van pipálva, a nap beszámít, az ösvény egy kővel előrébb lép, és nő a 🔥 sorozatod (napi feladatok nélkül egyetlen „✓ Ma megcsináltam” gomb van). A feladat melletti 🔁 gomb hozzáadja a Rutinomhoz egy általad választott órában: ha ott kipipálod, a célban is kipipálódik, és fordítva. Egy sima cél mérföldkövei ugyanígy hozzáadhatók a Rutinomhoz.",
