    vision_tagline: "Nagy célok, kis lépések.",
    faq_a_app_tour: "A bemutató egyszer automatikusan megnyílik, az első belépéskor. A részeivel kezdődik – koppints egyre, hogy egyből oda ugorj –, aztán megmutatja az alkalmazás minden részét (a kezdőképernyőt, az AI-asszisztenst és a menü minden elemét) és a Beállítások öt csoportját, mindegyiket rövid magyarázattal, és néhányba be is kukkant (például egy minta célútvonalba, a táskába és a Google Calendarba). A Tovább előre visz, a Vissza visszalép, a Rész átugrása a következő részre ugrik, az ✕ pedig bezárja a bemutatót. Bármikor újranézheted a Beállítások > Súgó és használat > Alkalmazás bemutató menüpontban, és ott folytathatod, ahol abbahagytad. A Tovább és a Vissza mindig ugyanott van a képernyő alján, számítógépen pedig a nyílbillentyűk is működnek.",
    faq_q_app_tour: "Hogyan nézhetem meg újra az alkalmazás bemutatót?",
    apptour_done_text: "Kérdésed van? A Beállításokban a Súgó és GYIK mindenre választ ad, ez a bemutató pedig mindig elérhető a Súgó és használat alatt.",
