    apptour_m_notes_link: "Húzz egy jegyzetet a mára, a holnapra vagy más dátumra, és feladat lesz belőle; a törölt jegyzetek a 🗑️ archívumban várnak.",
    apptour_m_notes_text: "Jegyzetek és ötletek egy listában.",
