    apptour_m_tables_text: "Saját táblázatok – ajándékok, sorozatok, listák – szöveg, szám, választás, dátum és ✓ oszlopokkal (Prémium).",
    apptour_m_study_link: "🪄 Az Okos Felosztás a ✅ Feladatok kártyán egy nagy feladatot lépésekre bont a naptáradban.",
    apptour_m_study_text: "A táskád: egy zseb minden életterületnek – benne füzetekkel, táblázatokkal és feladatokkal.",
    apptour_m_vision_link: "A mérföldkő melletti 📅 beteszi a naptárba; a kis lépések és a napi kihívás feladatai a Napom panelen jelennek meg, a haladás pedig egy számot vagy a testsúlyodat is követheti.",
    apptour_m_vision_text: "A céljaid kis lépésekből álló ösvények – a mai lépésekkel legfelül. Nézzünk be 👇",
    apptour_m_myweek_link: "Szinkronizál a Google Calendarral (a Beállításokban).",
    apptour_m_myweek_text: "A havi naptár, az ismétlődő heti feladatok emlékeztetőkkel és az összes dátumhoz kötött eseményed. Plusz a hét találkozóinak papírnaptára 🤝.",
    apptour_m_newme_link: "Minden beleszámít a Napi Étkezéskövetőbe és a Napom részbe; a testsúly közös a Kalória- és testsúlymutatókkal.",
    apptour_m_newme_text: "1300 / 1500 kalóriás étkezési terv egy varázslatos játékvilágban: a mai menü ✓-vel, csere háromféleképpen – a menüből, a mentett ételeidből, vagy megírod az AI-nak, mit ettél, és kiszámolja a kalóriát – bevásárlólista, étkezési emlékeztetők és fejlődési út kitüntetésekkel, testméretekkel és fotókkal. Ráadásul 🏆 20 kihívás – a végén ajándékkal – és a hét kihívása.",
    apptour_ai_table_text: "Írd le, milyen táblázat kell – az AI megtervezi az oszlopait (Prémium).",
    apptour_ai_photo_link: "A Receptjeim közé kerül.",
    apptour_ai_photo_text: "Fotózz le egy leírt receptet – az AI kitölt helyetted egy új receptet.",
    apptour_ai_schedule_link: "Megjelennek a naptárban és a Napom részben.",
    apptour_ai_schedule_text: "Írd le a terveidet egyszerű szavakkal, egyszerieket vagy ismétlődőket – egyenesen a naptárba kerülnek.",
    apptour_ai_food_link: "Egyenesen a Napi Étkezéskövetőbe és a mai összesítésbe kerül.",
    apptour_ai_food_text: "Írd be, mit ettél – a kalóriák becslése és rögzítése automatikus.",
    apptour_newme_short_text: "Megnyitja a New Me-t – a mai menü rögtön a főképernyőn van.",
    apptour_ai_link: "A gombon lévő kis 1-es jelvény a napi „mi a legfontosabb ma” emlékeztető.",
    apptour_ai_text: "Írj egyszerű szavakkal, a többit az asszisztensed intézi: rögzíti a kalóriát, beteszi a terveket a naptárba, fotóról beolvas egy receptet és táblázatokat készít.",
    apptour_quicknote_link: "A 📝 és a 🛒 megnyitja a teljes listákat; a 🍎 egy mentett ételt rögzít a Napi Étkezéskövetőben.",
    apptour_quicknote_text: "Írj le valamit gyorsan – a Jegyzetekbe vagy egyenesen a Bevásárlólistára.",
    apptour_routine_link: "Egy szokás automatikusan rögzíthet egy edzést az Edzéskövetésben.",
    apptour_routine_text: "A napi rutinod óránként, fülekre bontva (gyerekek, tanulás, munka…). Pipálj ✓ minden nap, és építs szokásokat és sorozatokat; a 📅 az egész hónapot mutatja.",
    apptour_premium_text: "Feloldja a teljes AI-asszisztenst, a témákat, a betűtípusokat, a Táskámat és még sok mást.",
    apptour_note_text: "Öntapadós cetli az egész hétre. Benne a ⚙ fogaskerék 1–3 soros ellenőrzőlistát ad hozzá, és megváltoztatja a cetli színét és stílusát.",
    apptour_peek_link: "Ide kerülnek az AI, a naptár és a Google Calendar feladatai, a célok lépései – plusz a mai kalóriák 🔥 és a 🎯 hónap célja.",
    apptour_peek_text: "Minden, ami ma van, egy helyen – feladatok, találkozók, a rutinod és a kis lépések egyetlen idővonalon. Pipáld ki ✓ itt helyben.",
