    auth_consent_label: "Elolvastam és elfogadom a {terms} és az {privacy}, továbbá elmúltam 16 éves.",
    nm_bonus_sub: "Rövid olvasmány a mérlegelésről, a cél túllépéséről és a házon kívüli étkezésről",
    nm_bonus_label: "Bónusz",
