    nm_extras_hint: "A „Napi Étkezéskövető” képernyőről és a gyors hozzáadásból – már beleszámít a gyűrűbe.",
    nm_extras_title: "Ma a terven kívül",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Add meg az ital nevét és kalóriáját",
    nm_drink_more: "+ Még egy ital",
    nm_drink_add: "Hozzáadás",
    nm_drink_name_ph: "Ital (pl. gyümölcslé)",
    nm_drinks_hint: "Elég beírni az italt – a kalória automatikusan kiszámolódik, és a szám módosítható.",
    nm_slot_drinks: "Italok",
    faq_a_new_me_tracking: "Koppints a New Me tetején a következő küldetésre, majd a ✓ Megettem gombra, hogy a következő étkezést elfogyasztottnak jelöld – a teljes menü minden étkezés melletti ✓-vel „Az egész nap” nézetben található, oldalt, a mai étkezések pedig a kezdőképernyőn a Napomban is megjelennek – ott bármelyikre koppintva (vagy fölé víve az egeret) pontosan látszik, mit kell enni, ✓-vel és a Csere gombbal. Minden szinkronban van a Napi Étkezéskövetővel: a terv étkezései, az italok és bármi, amit máshol adsz hozzá (például egy kávé a gyors hozzáadásból), együtt számít a New Me-ben és a Napomban – semmi, amit már beírtál, nem íródik felül, és egy ✓ eltávolítása csak a New Me részét veszi ki. Amikor minden mai étkezés ki van pipálva, egy kis ünneplés jön. Az „Italok” alatt a nap italai kerülnek feljegyzésre – összesen legfeljebb ~150 kcal, vagyis nagyjából 3 ital, egyenként legfeljebb ~50 kcal. Elég beírni az ital nevét, és a kalóriát az AI automatikusan kitölti. A két kávé/tea sorban van egy „Tej? Mennyi?” mező is (például „kevés” vagy „50 ml”), és a számítás frissül; a szám hozzáadás előtt és után is módosítható. A névvel és kalóriával rendelkező ital automatikusan mentődik, amint továbblépsz – a Hozzáadás gombra koppintani nem kötelező. Koppints a ☆-ra egy ital mellett, hogy állandó italként mentsd – az állandó italok gombokként jelennek meg az Italok kártya tetején, és egy koppintással hozzáadhatók a naphoz. A ⭐ egy étkezést mentett étkezésként ment el. A „Napi táblázat” megmutatja, mit ettél, kalóriával és fehérjével. A kezdőképernyő tetején, a fókusz mód melletti kis 💎 közvetlenül megnyitja. A kalória- és fehérjeértékek AI-becslések, és hibákat tartalmazhatnak. Nem fogyott el az egész? Egy kipipált étkezés alatt a „Nem fogyott el az egész?” levonja az adag negyedét, felét vagy háromnegyedét – vagy amit beírsz, kiszámolva –, és a nap kalóriái frissülnek.",
    faq_q_new_me_tracking: "Hogyan működik a ✓, a csere és a kalóriák a New Me-ben?",
    faq_a_new_me_what: "A New Me egy különálló napi menüprogram két kész tervvel – 1300 vagy 1500 kalória –, 2 főétkezésből és 2 nassolásból, mindegyikhez 3 lehetőséggel. A teljes Prémiumot tartalmazza. Ára: havi $11.99 (bármikor lemondható) vagy egyszeri $99.99, örökre. A menüben a 💎 New Me pontból nyitható meg. Indulás előtt egy rövid kérdőív következik, amely egy elfogadandó orvosi nyilatkozattal kezdődik. A program csak általános tájékoztatás, és nem helyettesíti az orvost vagy a klinikai dietetikust.",
    faq_q_new_me_what: "Mi a New Me, és hogyan szerezhetem meg?",
