    quick_add_ai_limit_toast: "Az e havi MI-keret elfogyott, ezért egy gyorsabb (kevésbé pontos) becslés készült. A keret a következő hónapban megújul.",
    food_estimate_local_db_reasoning: "Az élelmiszer-adatbázisunkban található, nem MI-tipp. Koppints az „Ez nem stimmel” gombra, ha nem erre az ételre gondoltál.",
    food_clarify_milk_question: "A(z) {ingredient} az italba kevert tejhelyettesítő, vagy egy külön adag szilárd étel? Kérlek, add meg a mennyiséget is.",
    food_ai_fallback_toast: "A teljes MI-becslés most nem érhető el, ezért ez egy gyors, hozzávetőleges becslés. A kalóriát kézzel is szerkesztheted, vagy próbáld újra rögzíteni egy kis idő múlva.",
    daily_focus_badge_title: "Emlékeztető: mi a fontos ma",
    calendar_event_star_title: "Megjelölés fontosként",
    auth_password_placeholder_login: "Jelszó",
    routine_overview_no_checks: "Ebben a hónapban még nincs kipipálás - koppints a rutinelemeid melletti ✓-re azokon a napokon, amikor elvégzed őket.",
    faq_a_finance_cycle_day: "Alapértelmezés szerint a költségvetési összesítőd minden naptári hónap 1-jén nullázódik. Ha más napon kapod a fizetésed (mondjuk 10-én), állítsd be itt azt a napot - ekkor a havi összesítőd, az előzmények és a célköltségvetés attól a naptól a következő hónap ugyanazon napjáig tart, nem pedig 1-jétől a hónap végéig.",
    faq_q_finance_cycle_day: "Mit csinál a 'Havi költségvetés nullázásának napja' beállítás?",
    faq_a_quick_note_view_full_lists: "A menüben ☰ ott vannak a Jegyzetek és a Bevásárlólista. A Gyors Jegyzet ablakban (Fókusz módban) a Hozzáadás melletti kis 📝 és 🛒 is oda visz, a 🍎 pedig gyorsan beír egy mentett étkezést.",
    faq_q_quick_note_view_full_lists: "Hogyan láthatom a teljes Jegyzeteimet vagy a teljes Bevásárlólistát a Gyors Jegyzetből?",
    note_triage_otherdate: "Másik Dátum", note_triage_otherdate_modal_title: "Válassz dátumot", note_triage_otherdate_missing: "Kérlek, válassz dátumot", note_triage_success_otherdate: "Hozzáadva az ütemtervedhez!", notes_ai_placeholder_shopping: "Hozzáadás a listához",
    daily_greeting_morning: "Jó reggelt!", daily_greeting_afternoon: "Jó napot!", daily_greeting_evening: "Jó estét!", daily_greeting_night: "Jó éjszakát!", calorie_monthly_view_title: "Havi nézet", calorie_monthly_avg_label: "Napi átlag:", calorie_monthly_avg_empty: "Ebben a hónapban még nincs rögzített adat", calorie_monthly_day_total_label: "Napi összesen:", notes_ai_added_shopping: "Hozzáadva a bevásárlólistádhoz", quick_note_dest_notes: "📝 Jegyzetek", quick_note_dest_shopping: "🛒 Bevásárlólista",
    faq_q_calorie_monthly_view: "Hogyan láthatom a kalóriatörténetemet egy egész hónapra visszamenőleg?", faq_a_calorie_monthly_view: "A Kalória mérőszámok tartalmaz egy 'Havi nézet' kártyát naptárral - minden nap, amikor ételt rögzítettél, egy pontot kap, a rács felett pedig az adott hónap napi átlaga látható. Koppints egy napra, hogy pontosan lásd, mit ettél és mennyi volt az összesen. Ugyanez a bontás szerepel a Beállításokból letöltött Személyes jelentésben (PDF) is, ha a Kalória mérőszámok szakasz be van pipálva.",
    faq_q_calorie_stats_total_vs_average: "A heti/havi számok a Kalória mérőszámoknál összeg vagy átlag?", faq_a_calorie_stats_total_vs_average: "Mindkettő - a nagy szám az aktuális naptári hét/hónap során rögzített minden adat összege, az alatta lévő kis sor pedig a napi átlag. Az átlagot csak azokkal a napokkal osztjuk el, amikor ténylegesen rögzítettél valamit, nem 7-tel vagy a teljes hónappal - egy nap, amikor semmi sincs rögzítve, egyszerűen kimarad, nem számít 0-nak, és nem húzza le az átlagot.",
    faq_q_weight_note: "Hozzáadhatok megjegyzést egy testsúly-bejegyzéshez?", faq_a_weight_note: "Igen - a Rendszeres Testsúlykövetésben (a Táplálkozás és Mérések > Kalória- és testsúlymutatók alján található, a ⚖️ alatt) a testsúly/dátum mezők mellett van egy opcionális megjegyzés mező. Használd olyan kontextushoz, mint \"edzés után\" vagy \"reggeli mérés\" - ez megjelenik a bejegyzés mellett az előzménylistában.",
    faq_q_quick_note_shopping_list: "Tud a Gyors Jegyzet közvetlenül a bevásárlólistámhoz hozzáadni?", faq_a_quick_note_shopping_list: "Igen – a kezdőképernyő közepén lévő írósorban koppints az elején lévő 📝-re: 🛒 lesz belőle, és amit írsz, egyenesen a Bevásárlólistára kerül, a Jegyzetek kihagyásával.",
