    faq_q_daily_focus_prompt: "Mi az a kis emlékeztető, amely azt kérdezi, mi a legfontosabb teendőm ma?", faq_a_daily_focus_prompt: "Ez egy napi Premium emlékeztető: naponta egyszer egy kis „1” jelvény jelenik meg az AI asszisztens ikonján. Koppints a jelvényre, és megnyílik egy buborék, amely megkérdezi, mi a legfontosabb teendőd ma, és benne rögtön láthatsz 5 kész javaslatot (naponta változnak, egy egész évnyi különböző témán végigforogva, hogy mindig frissek maradjanak), valamint az 'Egyéb' lehetőséget a saját megfogalmazásodhoz - többet is választhatsz. Koppints a Hozzáadás gombra, és a választásaid kis emlékeztető címkékként jelennek meg az 'A Napom' tetején (ezek nem kipipálandó feladatok). Ha a ✕ gombbal bezárod, vagy mellé koppintasz, a jelvény csak elhalványul a nap hátralévő részére, ahelyett hogy eltűnne. Alapértelmezés szerint be van kapcsolva, de kikapcsolhatod a Beállítások > Személyre szabás és naptár részben. Ma nem megy? Koppints a „🌙 Ma nem” gombra – a jelvény holnapig eltűnik, utána a kérdés a szokásos módon visszatér. Az egyik javaslat a saját életedből jön – a hónap céljának következő lépése vagy a mai olvasás. Minden nap tiszta lappal indul.",
